INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('42b4793c-85e4-44a1-81ca-bb1c903662c6','fr_MZ','CCF_COLLECT_IP_ADDRESS_LABEL','Nous collectons des informations telles que les adresses IP (Internet Protocol), le nom de domaine, le type de navigateur, le système d''exploitation, la date et l''heure de la visite, les pages visitées, le numéro IMEI/IMSI, l''identifiant de l''appareil, les informations de localisation, les paramètres de langue, la marque et le modèle du combiné, etc. Cependant, aucune tentative n''est faite pour les relier à la véritable identité des personnes visitant l''application Urban DIGIT, le site Web, le chatbot Whatsapp, etc.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('189d49f4-bb61-4174-abd5-23cf25a62476','fr_MZ','CCF_PP_DATA_DO_WE_COLLECT_INFO_2_LABEL','Nous collectons des informations telles que les adresses IP (Internet Protocol), le nom de domaine, le type de navigateur, le système d''exploitation, la date et l''heure de la visite, les pages visitées, le numéro IMEI/IMSI, l''identifiant de l''appareil, les informations de localisation, les paramètres de langue, la marque et le modèle du combiné, etc. Cependant, aucune tentative n''est faite pour les relier à la véritable identité des personnes visitant l''application, le site Web, le chatbot Whatsapp, etc.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('193b1a13-8ca6-42fe-adcc-fe669cf3f9d4','fr_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_1_LABEL','Nous utilisons ces données pour vous offrir la meilleure expérience civique, par exemple en fournissant des systèmes numériques de règlement des réclamations, une prestation de services efficace, en créant des tableaux de bord des activités de l''ULB, etc. Les données ne sont traitées que sur la base d''un mandat légal et dans un but légitime et nécessaire (pour vous fournir les services que vous demandez et pour apporter des améliorations à la prestation et à l''administration des services, ainsi qu''à toute autre fin spécifiée par la loi).','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('cec3696a-bfdd-46d6-b298-b27901c8fc9b','fr_MZ','CCF_PP_REFERS_LABEL','Grâce au NOM DU PROGRAMME, vous pouvez accéder et bénéficier des services offerts par les services gouvernementaux de l''ÉTAT OU DE L''ULB, les services du gouvernement central, les organismes locaux et leurs agences et les organismes corporatifs/privés (services publics) (prestataires de services). Vous pouvez utiliser le site Web/l''application/les services de PROGRAM NAME de différentes manières, par exemple pour la découverte de services, l''utilisation de services, l''enregistrement de griefs, etc.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('84c12760-ce50-408a-b1db-19d191ed3778','fr_MZ','CCF_PROCESS_DISCLOSE_SHARE_INFO_LABEL','Nous utilisons ces données pour vous offrir la meilleure expérience civique, par exemple en fournissant des systèmes numériques de règlement des réclamations, une prestation de services efficace, en créant des tableaux de bord des activités de l''ULB, etc. Les données ne sont traitées que sur la base d''un mandat légal et dans un but légitime et nécessaire (pour vous fournir les services que vous demandez et pour apporter des améliorations à la prestation et à l''administration des services, ainsi qu''à toute autre fin spécifiée par la loi).','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
