INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fd0eecdb-e33b-48b7-aa84-3c81817d914f','pt_MZ','The community distributor administers SPAQ according to the child’s age, explains hygienic handling, and follows Directly Observed Treatment (DOT)?','O distribuidor comunitário administra o SPAQ de acordo com a idade da criança, explica o manuseio higiênico e segue o Tratamento Diretamente Observado (TDO).','mz','hcm-checklist',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('248b06a4-ba11-44cc-b09a-72926e2b47b8','pt_MZ','The community distributor asks the caregiver questions to determine if the child is eligible for QSM?','O distribuidor comunitário faz perguntas ao cuidador para determinar se a criança é elegível para o QSM.','mz','hcm-checklist',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('dcaf440f-6a5c-47e0-b324-e7ec73633241','pt_MZ','The community distributor asks the caregiver to observe the child for 30 minutes and report if the child vomits the medicine?','O distribuidor comunitário pede ao cuidador que observe a criança por 30 minutos e relate se a criança vomitar o medicamento.','mz','hcm-checklist',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('052f507f-739d-4f4a-9ac9-79988dd602a1','pt_MZ','The community distributor correctly completes all information on the QSM Child Registration Card?','O distribuidor comunitário preencheu corretamente todas as informações no Cartão de Registro Infantil QSM?','mz','hcm-checklist',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('564df6fb-6294-4355-90af-546b7314b754','pt_MZ','The community distributor correctly fills in the information in SALAMA?','O distribuidor comunitário preencheu corretamente as informações no SALAMA?','mz','hcm-checklist',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9136a2fd-d0d8-496c-9f86-95f1edc636fe','pt_MZ','The community distributor determines the child’s age and excludes children under 3 months and over 59 months?','O distribuidor comunitário determina a idade da criança e exclui crianças com menos de 3 meses e mais de 59 meses?','mz','hcm-checklist',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('20c385f0-891f-4e26-b9c7-a87cd33f3fc0','pt_MZ','The community distributor excludes children with fever, who are sick, have side effects from SP or AQ, have taken SP or AQ in the last 4 weeks, or have taken cotrimoxazole or medicines containing sulfonamides?','O distribuidor comunitário exclui crianças com febre, que estejam doentes, que apresentem efeitos colaterais de SP ou AQ, que tenham tomado SP ou AQ nas últimas 4 semanas, ou que tenham tomado cotrimoxazol ou medicamentos que contenham sulfonamidas?','mz','hcm-checklist',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c3d6219c-2408-43e3-b6f7-bdf46dde6584','pt_MZ','The community distributor explains how to fill out the QSM Child Registration Card and the importance of keeping it safe during the 4 cycles?','O distribuidor comunitário explica como preencher a Ficha de Inscrição Infantil QSM e a importância de mantê-la em segurança durante os 4 ciclos.','mz','hcm-checklist',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5192772f-3518-49c2-9d53-df4a5bb03848','pt_MZ','The community distributor explains when the caregiver should take the child to the Health Facility or APS?','O distribuidor comunitário explica quando o responsável deve levar a criança ao posto de saúde ou ao Serviço de Proteção ao Adulto (APS).','mz','hcm-checklist',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e5ebb48d-f00b-4028-96e1-b185a5e5492b','pt_MZ','The community distributor gives the caregiver 2 AQ tablets, explains how to administer them on subsequent days, and explains the importance of adherence?','O distribuidor comunitário entrega ao cuidador 2 comprimidos de AQ, explica como administrá-los nos dias seguintes e esclarece a importância da adesão ao tratamento.','mz','hcm-checklist',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e86f812f-7a06-44e7-a851-74f21fe57e8e','pt_MZ','The community distributor is prepared and has all the necessary materials to administer the QSM?','O distribuidor comunitário está preparado e possui todos os materiais necessários para administrar o QSM?','mz','hcm-checklist',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5c25ed45-5a50-48f8-a7c4-bf08b2e66e1f','pt_MZ','The community distributor maintains good hygiene and wears the campaign uniform?','O distribuidor comunitário mantém boa higiene e usa o uniforme da campanha?','mz','hcm-checklist',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('feff212e-f06f-4a04-938f-82ae0227852d','pt_MZ','The community distributor provides the caregiver with information about QSM?','O distribuidor comunitário fornece ao cuidador informações sobre o QSM?','mz','hcm-checklist',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3099279e-160e-4eb8-9a91-74604471d9d4','pt_MZ','The community distributor re-administers SPAQ if the child vomits the first dose within 30 minutes?','O distribuidor comunitário deve reaplicar o SPAQ se a criança vomitar a primeira dose em até 30 minutos?','mz','hcm-checklist',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5724af36-e3bc-4428-b016-b8bfe170ba48','pt_MZ','The community distributor refers all sick children, children with fever, or with side effects from SPAQ to the nearest health facility or APS and correctly completes the QSM referral form?','O distribuidor comunitário encaminha todas as crianças doentes, crianças com febre ou com efeitos colaterais do SPAQ para a unidade de saúde ou APS mais próxima e preenche corretamente o formulário de encaminhamento do QSM?','mz','hcm-checklist',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
