INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('27b0ef3a-1eca-406b-9eab-a6eab74f096c','fr_MZ','The community distributor explains how to fill out the QSM Child Registration Card and the importance of keeping it safe during the 4 cycles?','Le distributeur communautaire explique comment remplir la carte d''inscription de l''enfant QSM et l''importance de la conserver en lieu sûr pendant les 4 cycles.','mz','hcm-checklist',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3c7c6c41-e714-4651-91fb-3ef2d383d46e','fr_MZ','The community distributor explains when the caregiver should take the child to the Health Facility or APS?','Le distributeur communautaire explique quand le soignant doit emmener l''enfant au centre de santé ou aux services de protection de l''enfance ?','mz','hcm-checklist',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6fd10cf1-fb1a-4e3c-920c-704e7c8465d5','fr_MZ','The community distributor gives the caregiver 2 AQ tablets, explains how to administer them on subsequent days, and explains the importance of adherence?','Le distributeur communautaire remet au soignant 2 comprimés d''AQ, explique comment les administrer les jours suivants et explique l''importance de l''observance du traitement.','mz','hcm-checklist',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3b22028f-bd5a-4e33-9693-a3632a2a5453','fr_MZ','The community distributor is prepared and has all the necessary materials to administer the QSM?','Le distributeur communautaire est-il préparé et dispose-t-il de tout le matériel nécessaire pour administrer le QSM ?','mz','hcm-checklist',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('013a5b6f-82c2-4230-bb80-281691b3c60f','fr_MZ','The community distributor maintains good hygiene and wears the campaign uniform?','Le distributeur communautaire maintient une bonne hygiène et porte l''uniforme de la campagne ?','mz','hcm-checklist',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('31b04fdf-9dff-4e8d-a0b7-f6a0b719eb8f','fr_MZ','The community distributor provides the caregiver with information about QSM?','Le distributeur communautaire fournit au soignant des informations sur le QSM ?','mz','hcm-checklist',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('56598aff-27f0-4f95-b500-94d238c56fa8','fr_MZ','The community distributor re-administers SPAQ if the child vomits the first dose within 30 minutes?','Le distributeur communautaire administre-t-il une nouvelle dose de SPAQ si l''enfant vomit la première dose dans les 30 minutes ?','mz','hcm-checklist',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4576e08a-baee-429e-a5bf-f8ebb041a5de','fr_MZ','The community distributor refers all sick children, children with fever, or with side effects from SPAQ to the nearest health facility or APS and correctly completes the QSM referral form?','Le distributeur communautaire oriente tous les enfants malades, les enfants fiévreux ou présentant des effets secondaires du SPAQ vers l''établissement de santé ou le service de protection des adultes le plus proche et remplit correctement le formulaire d''orientation QSM ?','mz','hcm-checklist',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('374da016-8b6b-4ce2-83d2-e4b11bab6655','fr_MZ','Yes','Oui','mz','hcm-checklist',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
